custom_css:
/* ============================================================
 * Gruvbox Dark + HarmonyOS Sans SC
 * 从零编写，不基于任何模板
 * ============================================================ */

/* ---字体加载--- */
@import url('https://cdn.jsdelivr.net/npm/@fontsource/jetbrains-mono@5.0.0/index.css');
@import url('https://cdn.jsdelivr.net/npm/@lobehub/webfont-harmony-sans-sc@1.0.0/css/index-full.css');

/* ---字体变量--- */
:root {
  --font-sans: 'HarmonyOS Sans SC', system-ui, sans-serif;
  --font-serif: 'HarmonyOS Sans SC', system-ui, sans-serif;
  --font-mono: 'JetBrains Mono', 'Cascadia Code', ui-monospace, Menlo, Consolas, 'HarmonyOS Sans SC', monospace;
}

/* ---全局字体（排除图标）--- */
body {
  background-color: transparent !important;
  font-family: var(--font-sans);
}

.mes_text,
.mes_text p,
.mes_text span,
.ch_name,
.mesIDDisplay,
.mes_timer,
.tokenCounterDisplay {
  font-family: var(--font-sans);
}

/* 代码等宽 */
code, pre, .hljs, .katex,
.mes_text code, .mes_text pre,
.mes_text .hljs, .mes_text .hljs span,
pre code, pre code.hljs {
  font-family: var(--font-mono) !important;
}

/* ============================================================
 * 引号文本 - 左竖线 + 底色 + 微缩进 组合拳
 * SillyTavern 用 <q> 标签包裹引号文字
 * ============================================================ */
.mes_text q {
  font-family: var(--font-serif) !important;
  color: var(--SmartThemeQuoteColor) !important;
  background: color-mix(in srgb, var(--SmartThemeQuoteColor) 10%, transparent);
  border-left: 3px solid var(--SmartThemeQuoteColor);
  padding: 0 6px 0 8px;
  margin: 0 2px;
  border-radius: 0 4px 4px 0;
  text-decoration: none !important;
}

/* blockquote 也留着以防有用 */
.mes_text blockquote {
  font-family: var(--font-serif) !important;
  border-left: 3px solid var(--SmartThemeQuoteColor);
  background: color-mix(in srgb, var(--SmartThemeQuoteColor) 10%, transparent);
  padding: 8px 12px 8px 14px;
  margin: 4px 0 4px 8px;
  border-radius: 0 4px 4px 0;
}

/* ============================================================
 * 代码块
 * ============================================================ */
code {
  background-color: var(--SmartThemeShadowColor);
  border-radius: 3px;
  padding: 1px 4px;
  font-size: 0.9em;
}

pre {
  background-color: var(--SmartThemeShadowColor) !important;
  border-radius: 6px;
  padding: 12px;
  overflow-x: auto;
}

pre code {
  background: transparent !important;
  padding: 0;
  border-radius: 0;
}

pre code.hljs {
  background: transparent !important;
}

.hljs {
  background: var(--SmartThemeShadowColor);
  border-radius: 6px;
}

/* ============================================================
 * 滚动条
 * ============================================================ */
::-webkit-scrollbar {
  width: 6px;
}
::-webkit-scrollbar:horizontal {
  height: 6px;
}
::-webkit-scrollbar-track {
  background: transparent;
}
::-webkit-scrollbar-thumb {
  background: color-mix(in srgb, var(--SmartThemeQuoteColor) 50%, transparent);
  border-radius: 3px;
}
::-webkit-scrollbar-thumb:hover {
  background: var(--SmartThemeQuoteColor);
}

/* ============================================================
 * 顶栏
 * ============================================================ */
#top-bar {
  background-color: transparent !important;
  box-shadow: 0 1px 0 var(--SmartThemeBorderColor);
}

#top-settings-holder {
  box-shadow: 0 1px 0 var(--SmartThemeQuoteColor);
}

.drawer {
  background-color: var(--SmartThemeBorderColor);
}

.drawer:has(.openDrawer) {
  background-color: var(--SmartThemeBlurTintColor);
}

.drawer-content {
  background-color: var(--SmartThemeBlurTintColor);
  border-radius: 6px;
  box-shadow: 0 1px 0 var(--SmartThemeQuoteColor);
  border: 1px solid var(--SmartThemeBorderColor);
}

.drawer-icon {
  opacity: 0.5;
}

.drawer-icon:hover,
.drawer-icon.openIcon {
  opacity: 1;
}

/* ---抽屉标题--- */
.inline-drawer-header,
#top-settings-holder h4:not(#ai-config-button *):not(#rightNavHolder *),
.drawer-content h4.margin0 {
  border: 1px solid var(--SmartThemeBorderColor) !important;
  border-left: 3px solid var(--SmartThemeQuoteColor) !important;
  border-radius: 4px !important;
  background-image: none !important;
  background-color: color-mix(in srgb, var(--SmartThemeBorderColor) 60%, var(--SmartThemeBlurTintColor)) !important;
  padding: 4px 8px 4px 12px !important;
  margin-bottom: 4px !important;
}

.inline-drawer-icon {
  font-size: var(--mainFontSize);
}

/* ---标题--- */
.standoutHeader strong,
#right-nav-panel h2,
.drawer-content h3.margin0,
.drawer-content h4.margin0,
.popup h3:not(dialog *) {
  font-size: calc(var(--mainFontSize) * 1.15);
  font-weight: 600;
  letter-spacing: 0.03em;
  line-height: 2;
}

.standoutHeader strong::before,
#right-nav-panel h2::before,
.drawer-content h3.margin0::before,
.drawer-content h4.margin0::before,
.popup h3:not(dialog *)::before {
  content: none;
}

/* ============================================================
 * 输入框
 * ============================================================ */
input[type="text"],
input[type="number"],
input:not([type]),
textarea:not([type="search"]) {
  background-color: var(--SmartThemeShadowColor) !important;
  border: 1px solid var(--SmartThemeBorderColor) !important;
  border-radius: 4px;
}

input[type="text"]:focus,
input[type="number"]:focus,
input:not([type]):focus,
textarea:not([type="search"]):focus {
  border-color: var(--SmartThemeQuoteColor) !important;
}

textarea[type="search"] {
  background-color: transparent !important;
  border: none !important;
}

.text_pole {
  background-color: var(--SmartThemeShadowColor);
  border: 1px solid var(--SmartThemeBorderColor);
  border-radius: 4px;
}

/* ============================================================
 * 按钮
 * ============================================================ */
.menu_button {
  background-color: #1d2021;
  border: 1px solid var(--SmartThemeBorderColor);
  color: var(--SmartThemeBodyColor);
  border-radius: 4px;
}

.menu_button:hover {
  background-color: color-mix(in srgb, var(--SmartThemeQuoteColor) 25%, var(--SmartThemeShadowColor));
  border-color: var(--SmartThemeQuoteColor);
}

#delete_button,
#dialogue_del_mes_ok,
#dialogue_popup_ok,
.redWarningBG,
.red_button,
.mes_edit_cancel.menu_button {
  background-color: rgba(204, 36, 29, 1) !important;
  color: #fff !important;
}

.mes_button,
.mes_edit_buttons {
  filter: none !important;
}

.fa-solid:not(#load-spinner) {
  text-shadow: none !important;
}

/* ============================================================
 * 下拉框
 * ============================================================ */
select {
  background-color: var(--SmartThemeShadowColor) !important;
  color: var(--SmartThemeBodyColor);
  border: 1px solid var(--SmartThemeBorderColor) !important;
  border-radius: 4px;
  margin: 4px 0 !important;
}

select option:checked {
  color: var(--SmartThemeBlurTintColor);
  background-color: var(--SmartThemeBodyColor) !important;
}

select option {
  background-color: var(--SmartThemeBlurTintColor) !important;
}

/* ============================================================
 * 勾选框
 * ============================================================ */
input[type="checkbox"] {
  width: calc(var(--mainFontSize) * 0.9);
  height: calc(var(--mainFontSize) * 0.9);
  border: none;
  border-radius: 3px;
  background-color: var(--SmartThemeShadowColor);
  filter: none;
  box-shadow: 0 0 0 1px var(--SmartThemeEmColor);
}

input[type="checkbox"]::before {
  box-shadow: inset 1em 1em var(--SmartThemeQuoteColor);
}

/* ============================================================
 * 滑动条
 * ============================================================ */
input[type="range"] {
  background-color: var(--SmartThemeShadowColor) !important;
  border-radius: 4px;
  box-shadow: none;
}

input[type="range"]::-webkit-slider-thumb {
  background-color: var(--SmartThemeQuoteColor);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--SmartThemeQuoteColor) 40%, transparent);
  border-radius: 50%;
  width: 10px;
  height: 10px;
}

/* ============================================================
 * 盒子/面板
 * ============================================================ */
#left-nav-panel,
#right-nav-panel,
#character_popup,
#dialogue_popup,
#chat,
.draggable,
#select_chat_popup,
.popup:not(.transparent_dialogue_popup),
.drawer-content {
  padding: 10px;
  background-color: var(--SmartThemeBlurTintColor);
  border-radius: 6px;
  border: 1px solid var(--SmartThemeBorderColor);
}



#dialogue_popup_text {
  padding: 0 10px 0 0;
}

/* ---列表--- */
.list-group,
.options-content {
  border: 1px solid var(--SmartThemeBorderColor);
  border-radius: 5px;
  background-color: var(--SmartThemeShadowColor) !important;
}

#options {
  background-color: transparent !important;
  padding: 0;
}

/* ---头像--- */
.avatar img,
body.big-avatars .avatar img {
  box-shadow: none;
  border: none;
  border-radius: 6px;
}

#rm_button_characters,
#rm_button_panel_pin_div,
#lm_button_panel_pin_div,
#WI_button_panel_pin_div,
#char_connections_button {
  font-size: var(--mainFontSize);
}

/* ============================================================
 * 聊天区域
 * ============================================================ */
#sheld {
  top: calc(var(--topBarBlockSize));
  height: calc(100dvh - var(--topBarBlockSize) - 1px);
}

#chat {
  overflow-y: scroll;
  scrollbar-gutter: stable;
  align-items: stretch;
  max-height: calc(100dvh - var(--topBarBlockSize) - 20px) !important;
  padding: 8px 8px 8px 8px;
  background-color: var(--SmartThemeChatTintColor);
}

.mesAvatarWrapper .avatar {
  margin: calc(var(--mainFontSize) * 0.6) 0 calc(var(--mainFontSize) * 0.4) 0;
}

.mesIDDisplay,
.mes_timer,
.tokenCounterDisplay {
  display: block;
  color: var(--SmartThemeEmColor);
  font-size: calc(var(--mainFontSize) * 0.75);
  opacity: 0.7;
}

#chat .ch_name {
  position: relative;
  align-items: flex-end;
  padding: calc(var(--mainFontSize) * 0.8) 0;
  font-weight: 500;
}

#chat .ch_name::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 1px;
  background-color: var(--SmartThemeEmColor);
}

.mes {
  border: none !important;
  background-color: var(--SmartThemeChatTintColor) !important;
}

.mes_text {
  padding: calc(var(--mainFontSize) * 0.8) 0 0 0;
  line-height: 1.8;
}



.last_mes .mes_text {
  padding-right: 0;
}

.last_mes .mesAvatarWrapper {
  padding-bottom: 0;
}

div[is_user="false"].last_mes .mes_block {
  padding-bottom: 50px;
}

.last_mes .swipeRightBlock {
  margin: 0 10px 0 0;
}

/* swipes-counter 与箭头视觉中线对齐（柱状布局下整体居中、counter 不再撑高） */
.swipeRightBlock {
  align-items: center !important;
  justify-content: flex-end !important;
}
.swipes-counter {
  height: auto !important;
  line-height: 1 !important;
  margin: 0 !important;
  padding: 2px 5px !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  align-self: center !important;
}
.swipe_right {
  align-self: center !important;
}

div[is_user="true"] {
  background-color: var(--SmartThemeUserMesBlurTintColor) !important;
}

div[is_user="false"] {
  background-color: var(--SmartThemeBotMesBlurTintColor) !important;
}

div[is_user="true"] .avatar img {
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--SmartThemeUnderlineColor) 60%, transparent);
}

div[is_user="false"] .avatar img {
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--SmartThemeQuoteColor) 60%, transparent);
}

.swipe_left {
  left: 12px;
}

.swipeRightBlock {
  flex-direction: row-reverse;
  bottom: calc(var(--swipeCounterHeight) + var(--swipeCounterMargin));
}

#chat .mes.selected {
  background-color: rgba(204, 36, 29, 0.3) !important;
}

/* ---文档模式--- */
body.documentstyle #chat .ch_name::after { width: 0; }
body.documentstyle #chat .mes .mes_block { margin-right: 0; padding-bottom: 15px; }
body.documentstyle #chat .last_mes .mes_block { padding-bottom: 50px; }
body.documentstyle #chat .mes_text { margin-left: 0 !important; }

/* ---视觉小说模式--- */
body.waifuMode #chat {
  border: none;
  box-shadow: none;
}
body.waifuMode .zoomed_avatar { top: 70px; }

/* ============================================================
 * 推理块
 * ============================================================ */
.mes_reasoning_header {
  margin: 1em 0;
  padding: 7px 28px 7px 10px;
  background: color-mix(in srgb, var(--SmartThemeQuoteColor) 20%, transparent);
  border: 1px solid var(--SmartThemeQuoteColor);
  border-radius: 4px;
  color: var(--SmartThemeBodyColor);
}

.mes_reasoning_header span::before {
  content: none;
}

.mes_reasoning {
  border-left: 2px solid var(--SmartThemeQuoteColor);
}

/* ============================================================
 * 底栏
 * ============================================================ */
#form_sheld {
  margin: 0 auto;
}

#send_form {
  background-color: var(--SmartThemeBlurTintColor) !important;
  border: 1px solid var(--SmartThemeBorderColor) !important;
  border-radius: 6px;
  backdrop-filter: none;
  padding: 4px 8px;
  outline: none !important;
}

#send_form:focus,
#send_form:focus-within {
  outline: none !important;
  box-shadow: none !important;
}

#send_form textarea {
  background-color: transparent !important;
}

#send_form .fa-solid {
  font-size: calc(var(--mainFontSize) * 1.5);
}

/* ---QR--- */
#qr--bar > .qr--buttons .qr--button,
#qr--popout > .qr--body > .qr--buttons .qr--button {
  background-color: color-mix(in srgb, var(--SmartThemeQuoteColor) 25%, transparent);
  border-color: var(--SmartThemeQuoteColor) !important;
  border-radius: 4px !important;
}

#qr--bar > .qr--buttons .qr--button:hover,
#qr--popout > .qr--body > .qr--buttons .qr--button:hover {
  background-color: color-mix(in srgb, var(--SmartThemeQuoteColor) 45%, transparent) !important;
}

/* ============================================================
 * 提示词管理器
 * ============================================================ */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt {
  border-radius: 6px;
  background-color: var(--SmartThemeBlurTintColor);
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt:hover,
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt:focus {
  border-color: var(--SmartThemeQuoteColor);
  background-color: color-mix(in srgb, var(--SmartThemeQuoteColor) 15%, transparent);
}

/* ============================================================
 * 世界书
 * ============================================================ */
.world_entry {
  margin-top: 5px;
}

.wi-card-entry {
  border: none;
}

.select2-container .select2-selection--multiple {
  background-color: var(--SmartThemeBlurTintColor);
  border: none;
  border-radius: 4px;
}

.select2-container .select2-selection--multiple .select2-selection__choice,
.select2-container .select2-selection--single .select2-selection__choice {
  background-color: color-mix(in srgb, var(--SmartThemeUnderlineColor) 25%, transparent);
  border-radius: 3px;
}

/* ============================================================
 * 角色管理器
 * ============================================================ */
.character_select.is_fav .avatar {
  outline: 2px solid var(--SmartThemeQuoteColor);
}

.character_select.is_fav .ch_name {
  color: var(--SmartThemeQuoteColor);
}

#HotSwapWrapper > div::-webkit-scrollbar-thumb {
  background-color: var(--SmartThemeBorderColor);
}

/* ---背景图库--- */
.bg_example {
  box-shadow: none;
  border-color: var(--SmartThemeBorderColor);
  border-radius: 4px;
}

.bg_example.selected {
  border-color: var(--SmartThemeUnderlineColor);
}

/* ============================================================
 * 移动端适配
 * ============================================================ */
/* 移动端缩小头像，正文更宽 */
@media screen and (max-width: 1000px) {
  /* 手机端全部方角 */
  #sheld, #chat, #send_form, #top-settings-holder,
  #left-nav-panel, #right-nav-panel,
  .drawer-content, .mes, #form_sheld {
    border-radius: 0 !important;
  }
  #top-settings-holder,
  #top-settings-holder .drawer,
  #top-settings-holder .drawer-toggle,
  #top-settings-holder .drawer:first-child,
  #top-settings-holder .drawer:last-child,
  #top-settings-holder .drawer:first-child .drawer-toggle,
  #top-settings-holder .drawer:last-child .drawer-toggle {
    border-radius: 0 !important;
  }
  /* 头像保留圆角 */
  .avatar img, .mesAvatarWrapper .avatar {
    border-radius: 50% !important;
  }
  #left-nav-panel,
  #right-nav-panel {
    border-radius: 0 0 5px 5px;
  }
  .mes {
    position: relative !important;
    padding-top: 8px !important;
    overflow: visible !important;
  }
  /* 头像：中线对齐日期行；计数器整体蒙版在日期下 */
  .mesAvatarWrapper {
    position: absolute !important;
    top: 8px !important;
    left: 4px !important;
    right: 4px !important;
    width: auto !important;
    min-width: 0 !important;
    height: auto !important;
    flex: none !important;
    display: flex !important;
    flex-direction: row !important;
    flex-wrap: wrap !important;
    align-items: center !important;
    align-content: flex-start !important;
    gap: 0 !important;
    z-index: 2 !important;
    pointer-events: none !important;
  }
  .mesAvatarWrapper .avatar {
    position: absolute !important;
    left: 0 !important;
    /* 名字行约 1.3em + 间距 4px + 日期半高 0.6em - 头像半高 18px */
    top: calc(1.3em + 4px + 0.6em - 18px) !important;
    transform: none !important;
    width: 36px !important;
    height: 36px !important;
    min-width: 36px !important;
    min-height: 36px !important;
    margin: 0 !important;
    flex: 0 0 36px !important;
    pointer-events: auto !important;
  }
  .mesAvatarWrapper .avatar img {
    width: 36px !important;
    height: 36px !important;
  }
  .mesAvatarWrapper::after {
    content: none !important;
    display: none !important;
  }
  #chat .mes .mes_block {
    width: 100% !important;
    padding: 0 !important;
  }
  /* 名字区：名字一行；日期第二行；与计数器间距=名字-日期间距 */
  #chat .mes .ch_name {
    position: relative !important;
    padding: 0 3em 0 46px !important;
    min-height: 0 !important;
    margin: 0 0 28px 0 !important; /* 给整体蒙版计数器留空 */
    display: block !important;
    overflow: visible !important;
  }
  #chat .mes .ch_name > .flex-container.flex1,
  #chat .mes .ch_name > .flex1 {
    display: block !important;
    width: 100% !important;
    max-width: 100% !important;
    min-width: 0 !important;
    flex: unset !important;
  }
  #chat .mes .ch_name .alignItemsBaseline {
    display: flex !important;
    flex-wrap: wrap !important;
    align-items: center !important;
    column-gap: 6px !important;
    row-gap: 4px !important; /* 名字↔日期 */
    width: 100% !important;
    max-width: 100% !important;
    min-width: 0 !important;
  }
  #chat .mes .ch_name .name_text {
    flex: 1 1 100% !important;
    min-width: 0 !important;
    max-width: 100% !important;
    display: block !important;
    overflow: hidden !important;
    text-overflow: ellipsis !important;
    white-space: nowrap !important;
    line-height: 1.3 !important;
  }
  #chat .mes .ch_name .mes_ghost {
    flex: 0 0 auto !important;
  }
  #chat .mes .timestamp {
    display: inline-flex !important;
    align-items: center !important;
    white-space: nowrap !important;
    flex: 0 0 auto !important;
    line-height: 1.2 !important;
    margin: 0 !important;
    opacity: 0.8 !important;
    font-size: calc(var(--mainFontSize) * 0.78) !important;
  }
  #chat .mes .timestamp-icon {
    display: inline-block !important;
    width: 1em !important;
    height: 1em !important;
    flex: 0 0 1em !important;
    margin: 0 0 0 4px !important;
    vertical-align: middle !important;
    line-height: 1 !important;
  }
  #chat .mes .timestamp-icon,
  #chat .mes .timestamp-icon svg {
    width: 1em !important;
    height: 1em !important;
    max-width: 1em !important;
    max-height: 1em !important;
    display: inline-block !important;
    vertical-align: middle !important;
  }
  #chat .mes .ch_name::after {
    display: none !important;
  }
  #chat .mes .ch_name .mes_buttons {
    position: absolute !important;
    top: 0 !important;
    right: 0 !important;
    left: auto !important;
    width: auto !important;
    max-width: none !important;
    margin: 0 !important;
    display: flex !important;
    flex-wrap: nowrap !important;
    align-items: center !important;
    justify-content: flex-end !important;
    gap: 4px !important;
    overflow: visible !important;
    z-index: 8 !important;
  }
  #chat .mes .ch_name .mes_buttons .extraMesButtons {
    flex-wrap: wrap !important;
    overflow: visible !important;
    max-width: none !important;
  }

  #chat .mes .ch_name .mes_buttons .mes_button,
  #chat .mes .ch_name .mes_buttons .extraMesButtons > div {
    flex: 0 0 auto !important;
    opacity: 0.8 !important;
  }
  /* 整体蒙版计数器：流式横排不重叠，首尾圆角 */
  #chat .mes .mesIDDisplay,
  #chat .mes .mes_timer,
  #chat .mes .tokenCounterDisplay {
    position: static !important;
    display: inline-block !important;
    order: 2 !important;
    top: auto !important;
    left: auto !important;
    /* 顶距加大：日期行与计数器不再黏在一起 */
    margin: calc(1.3em + 4px + 1.2em + 10px) 0 0 0 !important;
    padding: 2px 8px !important;
    font-size: calc(var(--mainFontSize) * 0.72) !important;
    opacity: 0.85 !important;
    line-height: 1.3 !important;
    white-space: nowrap !important;
    max-width: none !important;
    overflow: visible !important;
    background: color-mix(in srgb, var(--SmartThemeBorderColor) 60%, transparent) !important;
    border-radius: 0 !important;
    pointer-events: auto !important;
    box-sizing: border-box !important;
  }
  #chat .mes .mesIDDisplay {
    margin-left: 46px !important;
    border-radius: 4px 0 0 4px !important;
  }
  #chat .mes .mes_timer:not(:empty) {
    }
  #chat .mes .tokenCounterDisplay:not(:empty) {
    border-radius: 0 4px 4px 0 !important;
    }
  #chat .mes .mes_timer:empty {
    display: none !important;
  }
  #chat .mes .tokenCounterDisplay:empty {
    display: none !important;
  }
  /* 仅楼层号 */
  #chat .mes:has(.mes_timer:empty):has(.tokenCounterDisplay:empty) .mesIDDisplay {
    border-radius: 4px !important;
  }
  /* 楼层号+token（无timer） */
  #chat .mes:has(.mes_timer:empty) .tokenCounterDisplay:not(:empty) {
    border-radius: 0 4px 4px 0 !important;
  }
  /* 楼层号+timer（无token） */
  #chat .mes:has(.tokenCounterDisplay:empty) .mes_timer:not(:empty) {
    border-radius: 0 4px 4px 0 !important;
  }
  /* 正文 */

  #chat .mes .mes_text {
    padding-left: 6px !important;
    padding-right: 2px !important;
    padding-top: 10px !important;
    padding-bottom: 40px !important;
    margin-top: 4px !important;
    border-top: 1px solid color-mix(in srgb, var(--SmartThemeEmColor) 28%, transparent) !important;
  }
  /* 推理块也别贴计数器 */
  #chat .mes .mes_reasoning_details,
  #chat .mes .mes_reasoning_header,
  #chat .mes details.mes_reasoning_details {
    margin-top: 6px !important;
  }


  /* 操作菜单：向下展开（#chat 滚动容器裁切向上菜单） */
  #chat .mes .ch_name {
    overflow: visible !important;
  }
  #chat .mes .ch_name .mes_buttons {
    position: absolute !important;
    top: 0 !important;
    right: 0 !important;
    overflow: visible !important;
    z-index: 30 !important;
  }
  #chat .mes .ch_name .mes_buttons .extraMesButtons.visible {
    display: flex !important;
    position: absolute !important;
    top: calc(100% + 6px) !important;
    bottom: auto !important;
    right: 0 !important;
    left: auto !important;
    width: max-content !important;
    max-width: min(92vw, 22em) !important;
    flex-wrap: wrap !important;
    justify-content: flex-end !important;
    gap: 4px !important;
    padding: 6px !important;
    border-radius: 6px !important;
    border: 1px solid var(--SmartThemeBorderColor) !important;
    background: color-mix(in srgb, var(--SmartThemeBlurTintColor) 96%, #000 4%) !important;
    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.4) !important;
    z-index: 999 !important;
    overflow: visible !important;
  }

  /* 编辑按钮：正方形 3+3，整行右对齐不黏左边 */
  #chat .mes .mes_edit_buttons {
    float: none !important;
    clear: both !important;
    position: relative !important;
    z-index: 4 !important;
    display: none;
    grid-template-columns: repeat(3, 2.25rem) !important;
    grid-auto-rows: 2.25rem !important;
    justify-content: end !important;
    justify-items: center !important;
    align-items: center !important;
    gap: 6px !important;
    width: max-content !important;
    max-width: 100% !important;
    margin: 6px 4px 8px auto !important;
    margin-left: auto !important;
    padding: 4px 4px 4px 0 !important;
    box-sizing: border-box !important;
    overflow: visible !important;
  }
  #chat .mes .mes_edit_buttons[style*="flex"],
  #chat .mes .mes_edit_buttons[style*="inline-flex"] {
    display: grid !important;
  }
  #chat .mes .mes_edit_buttons .menu_button {
    flex: none !important;
    width: 2.25rem !important;
    height: 2.25rem !important;
    min-width: 2.25rem !important;
    max-width: 2.25rem !important;
    min-height: 2.25rem !important;
    max-height: 2.25rem !important;
    aspect-ratio: 1 / 1 !important;
    padding: 0 !important;
    margin: 0 !important;
    box-sizing: border-box !important;
    opacity: 0.85 !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
  }
  #chat .mes .mes_edit_buttons .mes_edit_done { order: 1 !important; }
  #chat .mes .mes_edit_buttons .mes_edit_copy { order: 2 !important; }
  #chat .mes .mes_edit_buttons .mes_edit_cancel { order: 3 !important; }
  #chat .mes .mes_edit_buttons .mes_edit_up { order: 4 !important; }
  #chat .mes .mes_edit_buttons .mes_edit_down { order: 5 !important; }
  #chat .mes .mes_edit_buttons .mes_edit_delete { order: 6 !important; }
  #chat .mes .mes_edit_buttons .mes_edit_add_reasoning { order: 7 !important; }
