/* ============================================================
 * 背景层 - v3.1 新增
 * body 底色 + #chat 透明 + 暗纹叠加
 * ============================================================ */

body {
  background-color: #1d2021 !important;
}

/* 全屏暗色遮罩（聊天区域外） */
body::before {
  content: "";
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background-color: rgba(29, 32, 33, 0.92);
  pointer-events: none;
  z-index: 0;
}

/* 暗纹叠加层（在遮罩之上，聊天区之下） */
body::after {
  content: "" !important;
  position: fixed !important;
  top: 0 !important; left: 0 !important; right: 0 !important; bottom: 0 !important;
  background-image:
    repeating-linear-gradient(45deg, transparent, transparent 35px, rgba(131, 165, 152, 0.008) 35px, rgba(131, 165, 152, 0.008) 70px),
    repeating-linear-gradient(-45deg, transparent, transparent 35px, rgba(131, 165, 152, 0.008) 35px, rgba(131, 165, 152, 0.008) 70px) !important;
  pointer-events: none !important;
  z-index: 0 !important;
}

/* #chat 用 JSON 字段的 chat_tint_color（已改为 0.75 透明） */
/* 消息背景透明，让 chat_tint 透过来 */
.mes {
  background-color: transparent !important;
}

div[is_user="true"],
div[is_user="false"] {
  background-color: transparent !important;
}

/* ============================================================
 * 图标悬停发光动效 - v3.2
 * ============================================================ */

/* 所有交互图标统一 transition */
.interactable,
.fa-solid:not(#load-spinner),
.drawer-icon,
.menu_button .fa-solid,
#send_form .fa-solid,
#send_form a,
#top-settings-holder .fa-solid,
#top-bar .fa-solid {
  transition: filter 0.35s ease-out, transform 0.35s ease-out;
}

/* 通用 hover 发光 + 放大 */
.interactable:hover,
.fa-solid:not(#load-spinner):hover,
.drawer-icon:hover,
#top-bar .fa-solid:hover {
  filter: drop-shadow(0 0 4px rgba(131, 165, 152, 0.4));
}

/* 底部三按钮更强发光 + 放大 */
#send_form .fa-solid:hover,
#send_form a:hover {
  filter: drop-shadow(0 0 6px rgba(131, 165, 152, 0.6));
}

/* 按钮内图标放大 */


/* 角色头像悬停微光 */
.avatar img,
.character_select .avatar img {
  transition: filter 0.35s ease-out;
}

.avatar img:hover,
.character_select:hover .avatar img {
  filter: drop-shadow(0 0 6px rgba(131, 165, 152, 0.3));
}

/* ============================================================
 * 底部三按钮各自动效 - v3.3 新增
 * 汉堡菜单→抖动 / 魔杖→旋转 / 发送→书写摆动
 * ============================================================ */

/* --- 汉堡菜单：hover 抖动 --- */
#options_button .fa-solid,
#options_button {
  transition: filter 0.35s ease-out;
}

#options_button:hover .fa-solid,
#options_button:hover {
  animation: icon-shake 0.4s ease-in-out;
  filter: drop-shadow(0 0 4px rgba(131, 165, 152, 0.4));
}

@keyframes icon-shake {
  0%, 100% { transform: translateX(0) rotate(0); }
  20% { transform: translateX(-2px) rotate(-3deg); }
  40% { transform: translateX(2px) rotate(3deg); }
  60% { transform: translateX(-2px) rotate(-3deg); }
  80% { transform: translateX(2px) rotate(3deg); }
}

/* --- 魔杖：hover 旋转 --- */
#extensionsMenuButton {
  transition: filter 0.35s ease-out;
}

#extensionsMenuButton:hover {
  filter: drop-shadow(0 0 4px rgba(131, 165, 152, 0.4));
}

@keyframes icon-spin {
  0% { transform: rotate(0); }
  100% { transform: rotate(360deg); }
}

/* --- 发送按钮：hover 发光 + active 变暗（不用transform防撑边框） --- */
#send_but {
  transition: filter 0.35s ease-out, opacity 0.2s ease-out;
  filter: drop-shadow(0 0 2px rgba(131, 165, 152, 0.2));
}

#send_but:hover {
  filter: drop-shadow(0 0 8px rgba(131, 165, 152, 0.6));
}

#send_but:active {
  filter: drop-shadow(0 0 4px rgba(131, 165, 152, 0.3));
  opacity: 0.7;
}



/* ============================================================
 * 发送按钮 - mdi:feather 羽毛笔 + 书写轨迹动效 - v3.6
 * ============================================================ */
#send_but::before {
  content: "" !important;
  display: inline-block !important;
  width: 1.2em !important;
  height: 1.2em !important;
  background-image: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2024%2024%22%3E%3Cpath%20fill%3D%22%23b8bb26%22%20d%3D%22M22%202s-7.64-.37-13.66%207.88C3.72%2016.21%202%2022%202%2022l1.94-1c1.44-2.5%202.19-3.53%203.6-5c2.53.74%205.17.65%207.46-2c-2-.56-3.6-.43-5.96-.19C11.69%2012%2013.5%2011.6%2016%2012l1-2c-1.8-.34-3-.37-4.78.04C14.19%208.65%2015.56%207.87%2018%208l1.21-1.93c-1.56-.11-2.5.06-4.29.5c1.61-1.46%203.08-2.12%205.22-2.25c0%200%201.05-1.89%201.86-2.32%22%2F%3E%3C%2Fsvg%3E"), url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%20100%204%22%20preserveAspectRatio%3D%22none%22%3E%3Cpath%20d%3D%22M0%202%20Q25%200%2050%202%20T100%202%22%20fill%3D%22none%22%20stroke%3D%22%23b8bb26%22%20stroke-width%3D%222%22%20stroke-linecap%3D%22round%22%2F%3E%3C%2Fsvg%3E") !important;
  background-repeat: no-repeat, no-repeat !important;
  background-position: center, left 100% !important;
  background-size: contain, 0% 2px !important;
  transition: background-size 0.8s ease-out, transform 0.3s ease-out !important;
  transform-origin: 50% 80% !important;
}

#send_but:hover::before {
  background-size: contain, 100% 2px !important;
  animation: quill-swing 1.5s ease-in-out infinite !important;
}

@keyframes quill-swing {
  0%, 100% { transform: rotate(-5deg); }
  50% { transform: rotate(5deg); }
}

/* 书写轨迹 */
#send_but {
  position: relative !important;
}

#send_but::after {
  content: "" !important;
  position: absolute !important;
  bottom: 0 !important;
  left: 50% !important;
  width: 0 !important;
  height: 1px !important;
  background: linear-gradient(90deg, transparent, #b8bb26, transparent) !important;
  pointer-events: none !important;
}

#send_but:hover::after {
  animation: quill-trail 1.5s ease-in-out infinite !important;
}

@keyframes quill-trail {
  0% { width: 0; left: 50%; opacity: 0; }
  30% { opacity: 1; }
  50% { width: 120%; left: -10%; opacity: 1; }
  70% { opacity: 1; }
  100% { width: 0; left: 50%; opacity: 0; }
}

